(160342, 8755, 5376, '<td valign="top">oh I like this!!!!</td>', 'oh I like this!!!!', '2002-11-25 17:46:00.000000', NULL, 1),
(160343, 8755, 3447, '<td valign="top">The loose nut fringe.  All good tax paying, productive citizens.  A 6 for the photograph - zero for the sentiment from a WWll veteran.    6     JEM</td>', 'The loose nut fringe.  All good tax paying, productive citizens.  A 6 for the photograph - zero for the sentiment from a WWll veteran.    6     JEM', '2002-11-25 21:56:00.000000', NULL, 1),
(160344, 8755, 4267, '<td valign="top">whew this one requires putting ones personal feelings aside to give an honest score.. lol shame on you! good impact to go with the stories headline<br/>~anachronite</td>', 'whew this one requires putting ones personal feelings aside to give an honest score.. lol shame on you! good impact to go with the stories headline~anachronite', '2002-11-25 22:56:00.000000', NULL, 1),
