(160427, 8758, 4210, '<td valign="top">Nice colours</td>', 'Nice colours', '2002-11-29 21:13:00.000000', NULL, 1),
(160428, 8758, 4648, '<td valign="top">Would have been great picture if it had been left natural color - green grass and blue sky.  Good focus and nice directional shot.  Really missing color.  PTL6</td>', 'Would have been great picture if it had been left natural color - green grass and blue sky.  Good focus and nice directional shot.  Really missing color.  PTL6', '2002-11-29 23:49:00.000000', NULL, 1),
